import com.google.gson.*;
import java.sql.*;
import java.util.*;

/** Read-only evidence, not recommendations to drop indexes or claims of recoverability. */
final class DatabaseEvidence {
  record Source(String id,String title,String sql,String note,Object... args) {}
  static Source source(String id,String title,String sql,String note,Object... args){return new Source(id,title,sql,note,args);}
  static Object read(Connection c,String engine,JsonObject p)throws SQLException {
    String panel=Main.str(p,"panel","");if(!Set.of("indexes","backups","connections").contains(panel))throw new IllegalArgumentException("Geçersiz kanıt paneli");
    String schema=Main.str(p,"schema",""),table=Main.str(p,"table","");var sources=new ArrayList<Source>();
    if(panel.equals("connections")){
      if(engine.equals("postgresql")){
        sources.add(source("capacity","Bağlantı kapasitesi","SELECT current_setting('max_connections') AS max_connections,current_setting('superuser_reserved_connections') AS superuser_reserved_connections,current_setting('reserved_connections',true) AS reserved_connections,CASE WHEN pg_has_role(current_user,'pg_read_all_stats','MEMBER') THEN (SELECT count(*) FROM pg_stat_activity WHERE backend_type='client backend') END AS client_connections","Küme kapsamı; tam izleme yetkisi yoksa bağlantı toplamı bilinmiyor kalır. Ayrılmış yuvalar normal kullanıcı kapasitesi değildir. Pool sınırları ayrıca değerlendirilmelidir."));
        sources.add(source("groups","Kullanıcı ve uygulama dağılımı","SELECT datname,usename,application_name,state,count(*) AS sessions FROM pg_stat_activity WHERE backend_type='client backend' GROUP BY datname,usename,application_name,state ORDER BY count(*) DESC","Küme kapsamı. Yetkisiz oturum ayrıntıları NULL olabilir; NULL aktif/boş demek değildir."));
        sources.add(source("transactions","Açık transaction ve bekleme","SELECT pid,usename,application_name,state,EXTRACT(EPOCH FROM (clock_timestamp()-xact_start))::bigint AS age_seconds,wait_event_type,wait_event,pg_blocking_pids(pid)::text AS blocking_pids FROM pg_stat_activity WHERE datname=current_database() AND xact_start IS NOT NULL AND pid<>pg_backend_pid() ORDER BY xact_start","Seçili DB. Transaction yaşı sorgu süresi değildir; idle in transaction bağlantıları da dahildir. SQL metni alınmaz."));
      }else if(engine.equals("mssql")){
        sources.add(source("capacity","Bağlantı yapılandırması","SELECT value_in_use AS configured_user_connections,CASE WHEN HAS_PERMS_BY_NAME(NULL,'SERVER','VIEW SERVER STATE')=1 OR HAS_PERMS_BY_NAME(NULL,'SERVER','VIEW SERVER PERFORMANCE STATE')=1 THEN (SELECT count(*) FROM sys.dm_exec_sessions WHERE is_user_process=1) END AS user_sessions FROM sys.configurations WHERE name='user connections'","Sunucu kapsamı; tam izleme yetkisi yoksa toplam bilinmiyor kalır. 0 otomatik yapılandırmadır; yüzde doluluk hesaplanmaz. Oturum sayısı pool kapasitesi veya fiziksel TCP bağlantı sayısı değildir."));
        sources.add(source("groups","Kullanıcı ve uygulama dağılımı","SELECT login_name,program_name,status,count(*) AS sessions FROM sys.dm_exec_sessions WHERE is_user_process=1 GROUP BY login_name,program_name,status ORDER BY count(*) DESC","Görünür sunucu oturumları. Diğer kullanıcıları görmek için sunucu izleme yetkisi gerekir."));
        sources.add(source("transactions","Açık transaction ve bekleme","SELECT s.session_id,s.login_name,s.program_name,s.status,a.transaction_id,a.transaction_begin_time,DATEDIFF_BIG(second,a.transaction_begin_time,GETDATE()) AS age_seconds,r.blocking_session_id,r.wait_type,r.wait_time FROM sys.dm_tran_active_transactions a JOIN sys.dm_tran_session_transactions t ON t.transaction_id=a.transaction_id JOIN sys.dm_exec_sessions s ON s.session_id=t.session_id LEFT JOIN sys.dm_exec_requests r ON r.session_id=s.session_id WHERE s.is_user_process=1 AND s.session_id<>@@SPID AND EXISTS(SELECT 1 FROM sys.dm_tran_database_transactions d WHERE d.transaction_id=a.transaction_id AND d.database_id=DB_ID()) ORDER BY a.transaction_begin_time","Seçili DB transaction'ları. MARS/çoklu request aynı oturumu birden çok satır gösterebilir; satır sayısı kullanıcı sayısı değildir. SQL metni alınmaz."));
      }else{
        sources.add(source("capacity","Instance kaynak sınırları","SELECT resource_name,current_utilization,max_utilization,initial_allocation,limit_value,con_id FROM v$resource_limit WHERE resource_name IN ('sessions','processes')","Instance kaynakları; PDB limiti/pool kapasitesi değildir. UNLIMITED sayısal yüzdeye çevrilmez."));
        sources.add(source("groups","Kullanıcı ve uygulama dağılımı","SELECT username,program,status,con_id,count(*) AS sessions FROM v$session WHERE type='USER' GROUP BY username,program,status,con_id ORDER BY count(*) DESC","Geçerli container'dan görünen oturumlar; RAC cluster toplamı değildir."));
        sources.add(source("transactions","Açık transaction ve bekleme","SELECT s.sid,s.serial#,s.username,s.program,s.status,s.con_id,t.start_date,ROUND((SYSDATE-t.start_date)*86400) AS age_seconds,t.used_ublk,s.blocking_session,s.event FROM v$transaction t JOIN v$session s ON s.taddr=t.addr WHERE s.type='USER' ORDER BY t.start_date","Geçerli instance/container görünürlüğü. Oracle salt okunur işlemleri her zaman V$TRANSACTION'da göstermez; boş liste hiçbir açık iş olmadığı anlamına gelmez. SQL metni alınmaz."));
      }
    }else if(panel.equals("indexes")){
      DbTools.q(schema,engine);DbTools.q(table,engine);DbTools.detail(c,engine,schema,table);
      if(engine.equals("postgresql")){
        sources.add(source("indexes","İndeks boyutu ve bağımlılıklar","SELECT i.relname AS index_name,pg_relation_size(i.oid) AS bytes,x.indisprimary AS primary_key,x.indisunique AS unique_index,x.indisvalid AS valid,x.indisready AS ready,EXISTS(SELECT 1 FROM pg_constraint k WHERE k.conindid=i.oid) AS constraint_dependency FROM pg_index x JOIN pg_class i ON i.oid=x.indexrelid JOIN pg_class t ON t.oid=x.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname=? AND t.relname=? ORDER BY i.relname","Constraint bağımlılığı indeksin silinebileceği anlamına gelmez.",schema,table));
        sources.add(source("usage","Okuma kullanımı","SELECT indexrelname AS index_name,idx_scan,idx_tup_read,idx_tup_fetch FROM pg_stat_user_indexes WHERE schemaname=? AND relname=? ORDER BY indexrelname","Sıfır kullanım gereksiz indeks kanıtı değildir; sayaçlar ayrıca sıfırlanabilir.",schema,table));
        sources.add(source("writes","Tablo yazma yükü","SELECT n_tup_ins,n_tup_upd,n_tup_del,n_tup_hot_upd FROM pg_stat_user_tables WHERE schemaname=? AND relname=?","Tablo sayaçlarıdır; indeks başına yazma süresi veya maliyeti değildir.",schema,table));
        sources.add(source("epoch","Sayaç bağlamı","SELECT stats_reset,pg_postmaster_start_time() AS server_start,current_setting('track_counts') AS track_counts FROM pg_stat_database WHERE datname=current_database()","DB reset zamanı tek indeksin ayrıca sıfırlanmasını kanıtlamaz."));
      }else if(engine.equals("mssql")){
        sources.add(source("indexes","İndeks ve constraint bağımlılıkları","SELECT i.name AS index_name,i.type_desc,i.is_primary_key,i.is_unique_constraint,i.is_unique,i.is_disabled,i.has_filter,i.filter_definition FROM sys.indexes i JOIN sys.tables t ON t.object_id=i.object_id JOIN sys.schemas s ON s.schema_id=t.schema_id WHERE s.name=? AND t.name=? AND i.index_id>0 ORDER BY i.name","Kısıtlar, filtre ve indeks türü birlikte değerlendirilmelidir.",schema,table));
        sources.add(source("usage","Okuma ve yazma işlemleri","SELECT i.name AS index_name,u.user_seeks,u.user_scans,u.user_lookups,u.user_updates,u.last_user_seek,u.last_user_scan,u.last_user_update FROM sys.indexes i JOIN sys.tables t ON t.object_id=i.object_id JOIN sys.schemas s ON s.schema_id=t.schema_id LEFT JOIN sys.dm_db_index_usage_stats u ON u.database_id=DB_ID() AND u.object_id=i.object_id AND u.index_id=i.index_id WHERE s.name=? AND t.name=? AND i.index_id>0 ORDER BY i.name","NULL bilinmiyor. user_updates işlem sayısıdır; satır sayısı veya süre değildir. Memory-optimized/spatial indeksler bu DMV kapsamında değildir.",schema,table));
        sources.add(source("size","Ayrılan alan","SELECT i.name AS index_name,SUM(CONVERT(bigint,p.used_page_count))*8192 AS used_bytes,SUM(CONVERT(bigint,p.reserved_page_count))*8192 AS reserved_bytes FROM sys.indexes i JOIN sys.tables t ON t.object_id=i.object_id JOIN sys.schemas s ON s.schema_id=t.schema_id JOIN sys.dm_db_partition_stats p ON p.object_id=i.object_id AND p.index_id=i.index_id WHERE s.name=? AND t.name=? AND i.index_id>0 GROUP BY i.name","Partition alanları aynı indeks altında toplanır.",schema,table));
        sources.add(source("epoch","Sunucu başlangıcı","SELECT sqlserver_start_time FROM sys.dm_os_sys_info","Başlangıç en uzun gözlem sınırıdır; detach, AUTO_CLOSE ve indeks yeniden oluşturma sayaçları daha sonra silebilir."));
      }else{
        sources.add(source("indexes","İndeks ve constraint bağımlılıkları","SELECT i.index_name,i.index_type,i.uniqueness,i.status,i.visibility,i.partitioned,i.last_analyzed,CASE WHEN EXISTS(SELECT 1 FROM all_constraints k WHERE k.index_owner=i.owner AND k.index_name=i.index_name) THEN 'YES' ELSE 'NO' END AS constraint_dependency FROM all_indexes i WHERE i.table_owner=? AND i.table_name=? ORDER BY i.index_name","last_analyzed kullanım sayacı veya reset zamanı değildir.",schema,table));
        sources.add(source("usage","Etkinleştirilmiş kullanım izlemesi","SELECT index_name,monitoring,used,start_monitoring,end_monitoring FROM user_object_usage WHERE table_name=? AND SYS_CONTEXT('USERENV','CURRENT_USER')=?","Yalnız bağlı kullanıcının önceden izlemeye alınmış indeksleri. İzleme otomatik açılmaz; boş sonuç kullanım yok anlamına gelmez. Nicel yazma maliyeti bu kaynakta bulunmaz.",table,schema));
        sources.add(source("size","Segment alanı","SELECT s.segment_name AS index_name,SUM(s.bytes) AS bytes FROM dba_segments s JOIN all_indexes i ON i.owner=s.owner AND i.index_name=s.segment_name WHERE i.table_owner=? AND i.table_name=? AND s.segment_type IN ('INDEX','INDEX PARTITION','INDEX SUBPARTITION') GROUP BY s.segment_name","DBA_SEGMENTS okuma yetkisi yoksa alan bilinmiyor kalır.",schema,table));
      }
    }else if(engine.equals("postgresql")){
      sources.add(source("backups","Tam yedek geçmişi",null,"PostgreSQL sistem kataloglarında pg_dump/pg_basebackup ve harici yedeklerin kalıcı başarı geçmişi bulunmaz. Yedek sağlayıcısı kanıtı henüz bağlı değil."));
      sources.add(source("archive","WAL arşivleme bağlamı","SELECT archived_count,last_archived_time,failed_count,last_failed_time,stats_reset,current_setting('archive_mode') AS archive_mode FROM pg_stat_archiver","WAL arşivleme tam yedek veya restore testi değildir. Geçmiş hata sayısı tek başına güncel arıza anlamına gelmez."));
      sources.add(source("restores","Restore doğrulaması",null,"Harici restore denemesi sonucu bu bağlantıdan doğrulanmıyor."));
    }else if(engine.equals("mssql")){
      sources.add(source("backups","Son full / differential / log yedekleri","WITH recent AS (SELECT type,backup_start_date,backup_finish_date,is_copy_only,is_damaged,has_backup_checksums,backup_size,compressed_backup_size,ROW_NUMBER() OVER(PARTITION BY type ORDER BY backup_finish_date DESC,backup_set_id DESC) AS rn FROM msdb.dbo.backupset WHERE database_name=DB_NAME() AND type IN ('D','I','L') AND backup_finish_date IS NOT NULL) SELECT type,backup_start_date,backup_finish_date,DATEDIFF_BIG(second,backup_finish_date,GETDATE()) AS age_seconds,is_copy_only,is_damaged,has_backup_checksums,backup_size,compressed_backup_size FROM recent WHERE rn=1 ORDER BY type","D=full, I=differential, L=log. COPY_ONLY ayrı gösterilir; yedek zinciri ve dosyanın varlığı doğrulanmaz. msdb geçmişi temizlenmiş olabilir."));
      sources.add(source("policy","Kurtarma modeli","SELECT name,recovery_model_desc FROM sys.databases WHERE name=DB_NAME()","SIMPLE modelde log yedeğinin olmaması tek başına hata değildir."));
      sources.add(source("restores","Son restore kayıtları","SELECT TOP (10) restore_date,restore_type,recovery,replace,stop_at,DATEDIFF_BIG(second,restore_date,GETDATE()) AS age_seconds FROM msdb.dbo.restorehistory WHERE destination_database_name=DB_NAME() ORDER BY restore_date DESC","Bu restore geçmişidir; kontrollü kurtarma testi veya DBCC doğrulaması değildir."));
      sources.add(source("failures","Başarısız yedek işleri",null,"backupset başarısız işlerin tam günlüğü değildir. SQL Agent/harici iş hata kaynağı henüz bağlı değil."));
    }else{
      sources.add(source("backups","Son RMAN işleri","SELECT session_key,input_type,status,start_time,end_time,ROUND((SYSDATE-end_time)*86400) AS age_seconds,input_bytes,output_bytes,output_device_type FROM v$rman_backup_job_details ORDER BY start_time DESC FETCH FIRST 50 ROWS ONLY","RMAN kontrol dosyası geçmişi; mevcut oturumun görebildiği CDB/PDB kapsamı. Harici exportlar ve silinmiş geçmiş kapsanmaz; COMPLETED dışında uyarı/hata ayrıca gösterilir."));
      sources.add(source("scope","Oracle bağlantı kapsamı","SELECT SYS_CONTEXT('USERENV','DB_NAME') AS db_name,SYS_CONTEXT('USERENV','CON_NAME') AS container_name,SYS_CONTEXT('USERENV','CON_ID') AS container_id FROM dual","RMAN iş kaydı tek başına seçili PDB'nin geri yüklenebilirliğini kanıtlamaz."));
      sources.add(source("restores","Restore doğrulaması",null,"RMAN başarı kaydı restore testi değildir; doğrulanmış restore denemesi kaynağı henüz bağlı değil."));
    }
    var parts=new ArrayList<Object>();
    for(var source:sources){var part=new LinkedHashMap<String,Object>();part.put("id",source.id);part.put("title",source.title);part.put("note",source.note);
      if(source.sql==null){part.put("status","unsupported");part.put("rows",List.of());}
      else try(PreparedStatement st=c.prepareStatement(source.sql)){
        st.setQueryTimeout(5);for(int i=0;i<source.args.length;i++)st.setObject(i+1,source.args[i]);
        try(ResultSet rs=st.executeQuery()){var data=Main.rows(rs,500,1_000_000);part.putAll(data);part.put("status",Boolean.TRUE.equals(data.get("truncated"))?"partial":((List<?>)data.get("rows")).isEmpty()?"unknown":"available");}
      }catch(SQLException e){part.put("status",DbTools.classify(e));part.put("message",e.getMessage());part.put("rows",List.of());}
      parts.add(part);
    }
    return Map.of("panel",panel,"engine",engine,"observedAt",System.currentTimeMillis(),"parts",parts,"schema",schema,"table",table);
  }
}
